    "ce": "# A box that moves to other glyphs — exported by Manim Formula Editor for ManimCE 0.22.\n# Render at 1920×1080, 60 fps:\n#     manim -r 1920,1080 --fps 60 ABoxThatMovesToOtherGlyphs.py ABoxThatMovesToOtherGlyphs\n# Every play and wait lasts a whole number of frames at 60 fps, so the video has\n# exactly 660 frames, like the editor's video export.\nfrom manim import *\n\n\ndef _glyphs(tex, layout):\n    \"\"\"The glyphs of `tex` in the editor's order. That order (MathJax's, or another\n    template's) can differ from Manim's, so the glyphs are matched by position: `layout`\n    holds each glyph's (x, y, width, height) relative to the formula centre, divided by the\n    formula height, and every real glyph is assigned to one entry with the least total\n    distance. Entries without a counterpart get an empty VMobject.\"\"\"\n    from scipy.optimize import linear_sum_assignment\n\n    real = tex.family_members_with_points()\n    glyphs = [VMobject() for _ in layout]\n    if len(real) != len(layout):\n        print(f\"Warning: Manim made {len(real)} glyphs of a formula the editor split into \"\n              f\"{len(layout)}; unmatched glyphs are not animated.\")\n    if not real or not layout:\n        return glyphs  # nothing to match (a formula without ink, such as \\quad)\n    centre, height = tex.get_center(), tex.get_height()\n    if height < 1e-6:\n        height = 1.0  # a flat mobject (a rule): the editor's layout is divided by 1 then too\n    have = np.array([\n        [*((g.get_center() - centre)[:2] / height), g.get_width() / height, g.get_height() / height]\n        for g in real\n    ])\n    want = np.array(layout, dtype=float)\n    cost = np.linalg.norm(want[:, None, :] - have[None, :, :], axis=2)\n    for i, j in zip(*linear_sum_assignment(cost)):\n        glyphs[i] = real[j]\n    return glyphs\n\n\nclass ABoxThatMovesToOtherGlyphs(Scene):\n    def construct(self):\n        self.camera.background_color = \"#000000\"\n\n        # series: 1+2+3+4+5+6\n        series = MathTex(r\"1+2+3+4+5+6\", font_size=96)\n        series_g = _glyphs(series, [\n            (-5.6925, 0.0468, 0.4532, 0.8775), (-4.5644, -0.0619, 0.8775, 0.8762), (-3.4304, 0.0468, 0.5257, 0.8775), (-2.295, -0.0619, 0.8775, 0.8762),\n            (-1.161, 0.0316, 0.5468, 0.9051), (-0.0257, -0.0619, 0.8775, 0.8762), (1.1083, 0.054, 0.5837, 0.892), (2.2437, -0.0619, 0.8775, 0.8762),\n            (3.3777, 0.0323, 0.5257, 0.9065), (4.513, -0.0619, 0.8775, 0.8762), (5.6459, 0.0323, 0.5463, 0.9065),\n        ])\n        series.move_to([0, 0.5, 0])\n\n        # s1: box, built on series where its clip starts\n\n        # 0 s – 1.2 s: series write\n        self.play(Write(VGroup(*series_g[:])), run_time=1.2)\n        # 1.2 s – 1.6 s\n        self.wait(0.4)\n        s1 = SurroundingRectangle(VGroup(*series_g[:5]), buff=0.15, color=\"#FFFF00\", corner_radius=0.12)\n        s1.set_z_index(1)\n        # 1.6 s – 2.4 s: s1 create\n        self.play(Create(s1), run_time=0.8)\n        # 2.4 s – 3.6 s\n        self.wait(1.2)\n        s1_to = SurroundingRectangle(VGroup(*series_g[6:]), buff=0.15, color=\"#FFFF00\", corner_radius=0.12)\n        # 3.6 s – 4.6 s: s1 tween\n        self.play(Transform(s1, s1_to), run_time=1)\n        # 4.6 s – 5.8 s\n        self.wait(1.2)\n        s1_to_2 = SurroundingRectangle(series, buff=0.15, color=\"#FFFF00\", corner_radius=0.12)\n        # 5.8 s – 6.8 s: s1 tween\n        self.play(Transform(s1, s1_to_2), run_time=1)\n        # 6.8 s – 10.2 s\n        self.wait(3.4)\n        # 10.2 s – 11 s: s1 fade_out, series fade_out\n        self.play(FadeOut(s1), FadeOut(series), run_time=0.8)\n",
    "gl": "# A box that moves to other glyphs — exported by Manim Formula Editor for ManimGL 1.7.\n# Render at 1920×1080, 60 fps:\n#     manimgl ABoxThatMovesToOtherGlyphs.py ABoxThatMovesToOtherGlyphs -w -r 1920x1080 --fps 60\n# Every play and wait lasts a whole number of frames at 60 fps, so the video has\n# exactly 660 frames, like the editor's video export.\nfrom manimlib import *\n\n\ndef _glyphs(tex, layout):\n    \"\"\"The glyphs of `tex` in the editor's order. That order (MathJax's, or another\n    template's) can differ from Manim's, so the glyphs are matched by position: `layout`\n    holds each glyph's (x, y, width, height) relative to the formula centre, divided by the\n    formula height, and every real glyph is assigned to one entry with the least total\n    distance. Entries without a counterpart get an empty VMobject.\"\"\"\n    from scipy.optimize import linear_sum_assignment\n\n    real = tex.family_members_with_points()\n    glyphs = [VMobject() for _ in layout]\n    if len(real) != len(layout):\n        print(f\"Warning: Manim made {len(real)} glyphs of a formula the editor split into \"\n              f\"{len(layout)}; unmatched glyphs are not animated.\")\n    if not real or not layout:\n        return glyphs  # nothing to match (a formula without ink, such as \\quad)\n    centre, height = tex.get_center(), tex.get_height()\n    if height < 1e-6:\n        height = 1.0  # a flat mobject (a rule): the editor's layout is divided by 1 then too\n    have = np.array([\n        [*((g.get_center() - centre)[:2] / height), g.get_width() / height, g.get_height() / height]\n        for g in real\n    ])\n    want = np.array(layout, dtype=float)\n    cost = np.linalg.norm(want[:, None, :] - have[None, :, :], axis=2)\n    for i, j in zip(*linear_sum_assignment(cost)):\n        glyphs[i] = real[j]\n    return glyphs\n\n\nclass ABoxThatMovesToOtherGlyphs(Scene):\n    default_camera_config = dict(background_color=\"#000000\")\n\n    def construct(self):\n\n        # series: 1+2+3+4+5+6\n        series = Tex(r\"1+2+3+4+5+6\", font_size=98.9888)\n        series_g = _glyphs(series, [\n            (-5.6925, 0.0468, 0.4532, 0.8775), (-4.5644, -0.0619, 0.8775, 0.8762), (-3.4304, 0.0468, 0.5257, 0.8775), (-2.295, -0.0619, 0.8775, 0.8762),\n            (-1.161, 0.0316, 0.5468, 0.9051), (-0.0257, -0.0619, 0.8775, 0.8762), (1.1083, 0.054, 0.5837, 0.892), (2.2437, -0.0619, 0.8775, 0.8762),\n            (3.3777, 0.0323, 0.5257, 0.9065), (4.513, -0.0619, 0.8775, 0.8762), (5.6459, 0.0323, 0.5463, 0.9065),\n        ])\n        series.move_to([0, 0.5, 0])\n\n        # s1: box, built on series where its clip starts\n\n        # 0 s – 1.2 s: series write\n        self.play(Write(VGroup(*series_g[:]), stroke_color=\"#FFFFFF\"), run_time=1.2)\n        # 1.2 s – 1.6 s\n        self.wait(0.4)\n        s1 = SurroundingRectangle(VGroup(*series_g[:5]), buff=0.15, color=\"#FFFF00\").round_corners(0.12)\n        s1_g = _glyphs(s1, [\n            (0, 0, 3.9321, 1),\n        ])\n        s1.set_z_index(1)\n        # 1.6 s – 2.4 s: s1 create\n        self.play(ShowCreation(VGroup(s1_g[0])), run_time=0.8)\n        # 2.4 s – 3.6 s\n        self.wait(1.2)\n        s1_to = SurroundingRectangle(VGroup(*series_g[6:]), buff=0.15, color=\"#FFFF00\").round_corners(0.12)\n        # 3.6 s – 4.6 s: s1 tween\n        self.play(Transform(s1, s1_to), run_time=1)\n        # 4.6 s – 5.8 s\n        self.wait(1.2)\n        s1_to_2 = SurroundingRectangle(series, buff=0.15, color=\"#FFFF00\").round_corners(0.12)\n        # 5.8 s – 6.8 s: s1 tween\n        self.play(Transform(s1, s1_to_2), run_time=1)\n        # 6.8 s – 10.2 s\n        self.wait(3.4)\n        # 10.2 s – 11 s: s1 fade_out, series fade_out\n        self.play(FadeOut(s1), FadeOut(series), run_time=0.8)\n"
